const slides=[...document.querySelectorAll('.slide')],tabs=[...document.querySelectorAll('[data-slide]')];let current=0;
function showSlide(index){current=Math.max(0,Math.min(slides.length-1,index));slides.forEach((slide,i)=>{slide.hidden=i!==current});tabs.forEach((tab,i)=>{if(i===current)tab.setAttribute('aria-current','step');else tab.removeAttribute('aria-current')});document.querySelector('#counter').textContent=(current+1)+' / '+slides.length;document.querySelector('#previous').disabled=current===0;document.querySelector('#next').disabled=current===slides.length-1;document.querySelector('#slide-status').textContent='Lámina '+(current+1)+' de '+slides.length+': '+document.querySelector('#title-'+current).textContent;}
tabs.forEach(tab=>tab.addEventListener('click',()=>showSlide(Number(tab.dataset.slide))));document.querySelector('#previous').addEventListener('click',()=>showSlide(current-1));document.querySelector('#next').addEventListener('click',()=>showSlide(current+1));
const scenarios=[{values:[42,35,23],name:'ESCENARIO BASE',reading:'Contrastar las razones de elección antes de priorizar una prueba.'},{values:[38,41,21],name:'ALTERNATIVA 1',reading:'En esta distribución inventada cambia el orden. En un proyecto real, revisaríamos qué evidencia explica esa diferencia.'},{values:[40,33,27],name:'ALTERNATIVA 2',reading:'Flexible aumenta su proporción en este ejemplo construido. Esto no estima el efecto de una intervención.'}];
document.querySelectorAll('[data-scenario]').forEach(button=>button.addEventListener('click',()=>{const index=Number(button.dataset.scenario),scenario=scenarios[index];document.querySelectorAll('[data-scenario]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.scenario)===index)));scenario.values.forEach((value,i)=>{document.querySelector('[data-value="'+i+'"]').textContent=value+'%';document.querySelector('[data-bar="'+i+'"]').style.width=value+'%'});document.querySelector('#scenario-reading').textContent=scenario.reading;document.querySelector('#scenario-caption').textContent=scenario.name+' · VALORES CONSTRUIDOS';document.querySelector('#scenario-status').textContent=scenario.name+': Esencial '+scenario.values[0]+'%, Completa '+scenario.values[1]+'%, Flexible '+scenario.values[2]+'%. Datos sintéticos.'}));
